package com.personal.crm;
import android.Manifest;
import android.content.*;
import android.content.pm.PackageManager;
import android.database.Cursor;
import android.net.Uri;
import android.provider.ContactsContract;
import org.json.*;
final class Contacts {
 static boolean allowed(Context c){return c.checkSelfPermission(Manifest.permission.READ_CONTACTS)==PackageManager.PERMISSION_GRANTED;}
 static JSONArray list(Context c)throws JSONException{if(!allowed(c))throw new SecurityException("Contacts permission required");JSONArray result=new JSONArray();String[] cols={ContactsContract.Contacts._ID,ContactsContract.Contacts.LOOKUP_KEY,ContactsContract.Contacts.DISPLAY_NAME_PRIMARY};try(Cursor cursor=c.getContentResolver().query(ContactsContract.Contacts.CONTENT_URI,cols,null,null,ContactsContract.Contacts.SORT_KEY_PRIMARY+" ASC")){if(cursor!=null)while(cursor.moveToNext()){String name=cursor.getString(2);if(name==null||name.trim().isEmpty())continue;result.put(new JSONObject().put("contactId",cursor.getString(0)).put("lookupKey",cursor.getString(1)).put("name",name));}}return result;}
 static JSONObject info(Context c,String lookup,String oldId)throws JSONException{if(!allowed(c))throw new SecurityException("Contacts permission required");Uri uri=ContactsContract.Contacts.getLookupUri(Long.parseLong(oldId),lookup);Uri resolved=ContactsContract.Contacts.lookupContact(c.getContentResolver(),uri);if(resolved==null)return null;String id,name,key;try(Cursor cursor=c.getContentResolver().query(resolved,new String[]{"_id",ContactsContract.Contacts.DISPLAY_NAME_PRIMARY,ContactsContract.Contacts.LOOKUP_KEY},null,null,null)){if(cursor==null||!cursor.moveToFirst())return null;id=cursor.getString(0);name=cursor.getString(1);key=cursor.getString(2);}return new JSONObject().put("contactId",id).put("lookupKey",key).put("name",name==null?"Unnamed contact":name).put("phone",first(c,ContactsContract.CommonDataKinds.Phone.CONTENT_URI,ContactsContract.CommonDataKinds.Phone.NUMBER,id));}
 private static String first(Context c,Uri uri,String field,String id){try(Cursor cursor=c.getContentResolver().query(uri,new String[]{field},ContactsContract.Data.CONTACT_ID+"=?",new String[]{id},ContactsContract.Data.IS_SUPER_PRIMARY+" DESC,"+ContactsContract.Data.IS_PRIMARY+" DESC")){return cursor!=null&&cursor.moveToFirst()&&cursor.getString(0)!=null?cursor.getString(0):"";}}
 static void refresh(Context c){if(!allowed(c))return;synchronized(CrmStore.LOCK){try{CrmStore store=new CrmStore(c);JSONObject data=store.read();JSONArray people=data.getJSONArray("people");boolean changed=false;for(int i=0;i<people.length();i++){JSONObject p=people.getJSONObject(i);if(p.optString("lookupKey").isEmpty())continue;JSONObject contact=info(c,p.getString("lookupKey"),p.getString("contactId"));if(contact==null)continue;for(String field:new String[]{"name","contactId","lookupKey","phone"})if(!p.optString(field).equals(contact.getString(field))){p.put(field,contact.get(field));changed=true;}}if(changed)store.write(data);}catch(JSONException|SecurityException|IllegalArgumentException ignored){/* Existing notes stay intact if a linked contact disappears or permission is revoked. */}}}
}
